(4557639, 657000, 54778, '<td valign="top">I like the b/w conversion and how you''ve caught the feel of the area but including the buildings on the right shakes the balance and they seem too overexposed.. Maybe if you''d walked just a little to the right and gotten the sharp corner of the building.. that would have made the composition more simple and perhaps stronger. Another problem here is the black plastic bags seem completely camouflaged.. maybe moving in closer to get more detail would have helped..</td>', 'I like the b/w conversion and how you''ve caught the feel of the area but including the buildings on the right shakes the balance and they seem too overexposed.. Maybe if you''d walked just a little to the right and gotten the sharp corner of the building.. that would have made the composition more simple and perhaps stronger. Another problem here is the black plastic bags seem completely camouflaged.. maybe moving in closer to get more detail would have helped..', '2008-03-12 10:03:02.000000', NULL, 1),
(4557644, 656957, 87898, '<td valign="top">the focus is great</td>', 'the focus is great', '2008-03-12 10:04:51.000000', NULL, 1),
(4557646, 656945, 54778, '<td valign="top">Great use of long exposure.. Perhaps the only thing missing is a distinct focal point that makes this picture stand out from other similar pictures..</td>', 'Great use of long exposure.. Perhaps the only thing missing is a distinct focal point that makes this picture stand out from other similar pictures..', '2008-03-12 10:05:20.000000', NULL, 1),
(4557651, 656812, 87898, '<td valign="top">the sky is a beautiful color!</td>', 'the sky is a beautiful color!', '2008-03-12 10:07:22.000000', NULL, 1),
(4557655, 656551, 54778, '<td valign="top">Really like the gritty feel of the image.. The contrast works well with the edititng but I almost missed the tar[inclusion of which makes the image cooler] so that''s the only part that I wish was better illuminated</td>', 'Really like the gritty feel of the image.. The contrast works well with the edititng but I almost missed the tar[inclusion of which makes the image cooler] so that''s the only part that I wish was better illuminated', '2008-03-12 10:09:08.000000', NULL, 1),
(4557661, 656883, 90256, '<td valign="top">Is it just me or is the moon blurred?</td>', 'Is it just me or is the moon blurred?', '2008-03-12 10:10:24.000000', NULL, 1),
(4557702, 657087, 90212, '<td valign="top">this is a good picture, but there isnt much to it.</td>', 'this is a good picture, but there isnt much to it.', '2008-03-12 10:27:17.000000', NULL, 1),
(4557704, 656805, 73115, '<td valign="top">Extra interior lighting or flash would have helped with the back lighting. The upper corners are too blown out.</td>', 'Extra interior lighting or flash would have helped with the back lighting. The upper corners are too blown out.', '2008-03-12 10:27:43.000000', NULL, 1),
(4557706, 655385, 73115, '<td valign="top">Hopefully everyone will start doing their part. Nice colors and detail.</td>', 'Hopefully everyone will start doing their part. Nice colors and detail.', '2008-03-12 10:28:56.000000', NULL, 1),
(4557715, 657122, 86902, '<td valign="top">wow, I really like this shot.  The composition is very well done and your background blur really frames your "chimneys" well.  Good luck, I give it an 8.</td>', 'wow, I really like this shot.  The composition is very well done and your background blur really frames your "chimneys" well.  Good luck, I give it an 8.', '2008-03-12 10:31:32.000000', NULL, 1),
(4557717, 657068, 86902, '<td valign="top">great colors</td>', 'great colors', '2008-03-12 10:32:13.000000', NULL, 1),
(4557724, 655925, 86902, '<td valign="top">I really like your concept, but I just wish the overall shot was brighter, maybe more illuminated?</td>', 'I really like your concept, but I just wish the overall shot was brighter, maybe more illuminated?', '2008-03-12 10:35:07.000000', NULL, 1),
(4557728, 657068, 89133, '<td valign="top">Love this shot,not the content,but if theres a way of making pollution attractive you''ve found it.I found judging this subject hard,was i looking for something shocking or a well taken photograph.I went for both,the shot is colourful and well cropped a very vibrant photograph,then you think....This is urban decay something all towns and cities the world over have and you feel disgusted that we are capable of living with this and worse.</td>', 'Love this shot,not the content,but if theres a way of making pollution attractive you''ve found it.I found judging this subject hard,was i looking for something shocking or a well taken photograph.I went for both,the shot is colourful and well cropped a very vibrant photograph,then you think....This is urban decay something all towns and cities the world over have and you feel disgusted that we are capable of living with this and worse.', '2008-03-12 10:36:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4557734, 656812, 81530, '<td valign="top">Very nice to see a completely different idea. Lovely shot.</td>', 'Very nice to see a completely different idea. Lovely shot.', '2008-03-12 10:39:19.000000', NULL, 1),
(4557740, 654873, 81530, '<td valign="top">I like that the photo isn''t crisp and clean. A good example of pollution.</td>', 'I like that the photo isn''t crisp and clean. A good example of pollution.', '2008-03-12 10:40:26.000000', NULL, 1),
(4557741, 656991, 54778, '<td valign="top">I believe this picture would have been better with more context[i.e. more sense of where it''s placed].. The narrow crop also doesn''t work well here..</td>', 'I believe this picture would have been better with more context[i.e. more sense of where it''s placed].. The narrow crop also doesn''t work well here..', '2008-03-12 10:40:49.000000', NULL, 1),
(4557744, 655436, 90212, '<td valign="top">this is a good picture, but you cant see that much of the graffiti.</td>', 'this is a good picture, but you cant see that much of the graffiti.', '2008-03-12 10:42:26.000000', NULL, 1),
(4557750, 656862, 89133, '<td valign="top">This is a nice clean photograph,but for some unknown reason i found it disturbing.While i''m in bed at night this flu is pumping out who knows what and furthermore does anyone care.Its probably only steam?</td>', 'This is a nice clean photograph,but for some unknown reason i found it disturbing.While i''m in bed at night this flu is pumping out who knows what and furthermore does anyone care.Its probably only steam?', '2008-03-12 10:44:50.000000', NULL, 1),
(4557778, 657051, 73115, '<td valign="top">The details are super sharp, but I find the overall picture quite uninteresting... sorry.</td>', 'The details are super sharp, but I find the overall picture quite uninteresting... sorry.', '2008-03-12 10:54:34.000000', NULL, 1),
(4557782, 656885, 54778, '<td valign="top">The whole setup seems interesting but I think you could have been more creative with the composition.. maybe moving in closer and framing it from the left with more variation in dof would have helped..</td>', 'The whole setup seems interesting but I think you could have been more creative with the composition.. maybe moving in closer and framing it from the left with more variation in dof would have helped..', '2008-03-12 10:55:43.000000', NULL, 1),
(4557784, 656816, 31535, '<td valign="top">I like the contrast from beautiful sky right to polluted sky left. I''m not sure if its a product of the shadow/highlights process, but something doesn''t look right along the bottom of the photo. It''s blotchy compared to the rest of the image.</td>', 'I like the contrast from beautiful sky right to polluted sky left. I''m not sure if its a product of the shadow/highlights process, but something doesn''t look right along the bottom of the photo. It''s blotchy compared to the rest of the image.', '2008-03-12 10:56:13.000000', NULL, 1),
(4557786, 656402, 54778, '<td valign="top">Very cool use of dof.. especially like the way the colour gradients..</td>', 'Very cool use of dof.. especially like the way the colour gradients..', '2008-03-12 10:56:41.000000', NULL, 1),
(4557790, 657122, 31535, '<td valign="top">I like the clarity of the cigarettes, and the beautifull blue sky really makes them stand out. Clever photo.</td>', 'I like the clarity of the cigarettes, and the beautifull blue sky really makes them stand out. Clever photo.', '2008-03-12 10:57:36.000000', NULL, 1),
(4557793, 656496, 90212, '<td valign="top">this is a really good picture, and i agree with the title.</td>', 'this is a really good picture, and i agree with the title.', '2008-03-12 10:58:25.000000', NULL, 1),
(4557794, 655609, 31535, '<td valign="top">Great colours, and the long exposure makes to smoke look really cool.</td>', 'Great colours, and the long exposure makes to smoke look really cool.', '2008-03-12 10:58:37.000000', NULL, 1),
(4557795, 656587, 80867, '<td valign="top">Good shot, wish the sky had a little more detail or the stacks showed some sort of pollution, nothing you can control though.</td>', 'Good shot, wish the sky had a little more detail or the stacks showed some sort of pollution, nothing you can control though.', '2008-03-12 10:59:11.000000', NULL, 1),
(4557797, 656862, 31535, '<td valign="top">Looks like an Area 51 bunker. Great capture of the stars.</td>', 'Looks like an Area 51 bunker. Great capture of the stars.', '2008-03-12 10:59:30.000000', NULL, 1),
(4557798, 656295, 80867, '<td valign="top">Good shot, I think it may be great in HDR which isn''t probably allowed on this challenge though.</td>', 'Good shot, I think it may be great in HDR which isn''t probably allowed on this challenge though.', '2008-03-12 10:59:44.000000', NULL, 1),
(4557804, 655436, 80867, '<td valign="top">I think of graffiti more as an art as long as it is done right, unique perspective though.</td>', 'I think of graffiti more as an art as long as it is done right, unique perspective though.', '2008-03-12 11:00:11.000000', NULL, 1),
(4557806, 657000, 80867, '<td valign="top">Love it, great shot, 9/10</td>', 'Love it, great shot, 9/10', '2008-03-12 11:00:22.000000', NULL, 1),
(4557807, 657055, 90212, '<td valign="top">this picture is really good, it makes me really sad everytime i look at. it makes me wonder what our world is coming to.</td>', 'this picture is really good, it makes me really sad everytime i look at. it makes me wonder what our world is coming to.', '2008-03-12 11:00:30.000000', NULL, 1),
(4557808, 656988, 54778, '<td valign="top">Interesting and different interpretation.. but maybe the model should been facing the camera slightly more so the full impact of her expression could have been felt..</td>', 'Interesting and different interpretation.. but maybe the model should been facing the camera slightly more so the full impact of her expression could have been felt..', '2008-03-12 11:00:43.000000', NULL, 1),
(4557809, 657055, 80867, '<td valign="top">Sad isn''t it...</td>', 'Sad isn''t it...', '2008-03-12 11:00:52.000000', NULL, 1),
(4557811, 656699, 80867, '<td valign="top">Love this, great perspective and very unique. 9/10</td>', 'Love this, great perspective and very unique. 9/10', '2008-03-12 11:01:19.000000', NULL, 1),
(4557814, 655436, 31535, '<td valign="top">I think a different angle would have shown the graffiti better, but the colours are great in this shot.</td>', 'I think a different angle would have shown the graffiti better, but the colours are great in this shot.', '2008-03-12 11:01:39.000000', NULL, 1),
(4557817, 656643, 80867, '<td valign="top">Captured all that I think about in one shot when I think of pollution. 8/10</td>', 'Captured all that I think about in one shot when I think of pollution. 8/10', '2008-03-12 11:01:59.000000', NULL, 1),
(4557820, 656883, 80867, '<td valign="top">Gross... Nice shot.</td>', 'Gross... Nice shot.', '2008-03-12 11:02:50.000000', NULL, 1),
(4557821, 657015, 31535, '<td valign="top">Nice reflection off the water. I think a bit more saturation would really add to this.</td>', 'Nice reflection off the water. I think a bit more saturation would really add to this.', '2008-03-12 11:03:02.000000', NULL, 1),
(4557825, 656694, 80867, '<td valign="top">Very sad, but he is so happy. Great shot.</td>', 'Very sad, but he is so happy. Great shot.', '2008-03-12 11:03:53.000000', NULL, 1),
(4557827, 655703, 80867, '<td valign="top">Great shot... Haha.</td>', 'Great shot... Haha.', '2008-03-12 11:04:29.000000', NULL, 1),
(4557833, 656098, 80867, '<td valign="top">Great shot</td>', 'Great shot', '2008-03-12 11:06:31.000000', NULL, 1),
(4557836, 656812, 39679, '<td valign="top">Awesome shot.  The lighting really makes this image interesting.  Nice work</td>', 'Awesome shot.  The lighting really makes this image interesting.  Nice work', '2008-03-12 11:06:52.000000', NULL, 1),
(4557859, 655424, 80867, '<td valign="top">Just sad and awful.</td>', 'Just sad and awful.', '2008-03-12 11:12:06.000000', NULL, 1),
(4557881, 656842, 91318, '<td valign="top">Love the colors!</td>', 'Love the colors!', '2008-03-12 11:20:41.000000', NULL, 1),
(4557884, 656334, 91318, '<td valign="top">Interesting combination of subjects.</td>', 'Interesting combination of subjects.', '2008-03-12 11:21:32.000000', NULL, 1),
(4557887, 656812, 91318, '<td valign="top">I love how the light shines through the bag.</td>', 'I love how the light shines through the bag.', '2008-03-12 11:22:36.000000', NULL, 1),
(4557916, 656561, 39679, '<td valign="top">It''s so common that people choose to have a shot in black and white for no good reason.  In this case, however, I think you really chose well.  There are so many interesting textures here and I can imagine that the color was probably muted and would have just been distracting.</td>', 'It''s so common that people choose to have a shot in black and white for no good reason.  In this case, however, I think you really chose well.  There are so many interesting textures here and I can imagine that the color was probably muted and would have just been distracting.', '2008-03-12 11:29:11.000000', NULL, 1),
(4557974, 655260, 89133, '<td valign="top">First i saw a well shot photo,but then you think wheres that smoke been and wheres it going,i''m glad that smoking has been banned in public places in the UK.</td>', 'First i saw a well shot photo,but then you think wheres that smoke been and wheres it going,i''m glad that smoking has been banned in public places in the UK.', '2008-03-12 11:47:57.000000', NULL, 1),
(4558015, 656098, 36382, '<td valign="top">Not sure about what you did to the contrast, but I do like the idea and the execution otherwise.  Good.</td>', 'Not sure about what you did to the contrast, but I do like the idea and the execution otherwise.  Good.', '2008-03-12 12:02:10.000000', NULL, 1),
(4558024, 657081, 53147, '<td valign="top">I like the boater in the shot and the colors are nice, but coming back to comment after voting it doesnt seem to have the same impact the initial view did. Not sure why though. Gave it a 7 first run through. Keeping it there.</td>', 'I like the boater in the shot and the colors are nice, but coming back to comment after voting it doesnt seem to have the same impact the initial view did. Not sure why though. Gave it a 7 first run through. Keeping it there.', '2008-03-12 12:10:17.000000', NULL, 1),
(4558025, 655703, 53147, '<td valign="top">Good photojournalistic feel to this image IMO. And how can you go wrong with Oscar.</td>', 'Good photojournalistic feel to this image IMO. And how can you go wrong with Oscar.', '2008-03-12 12:10:49.000000', NULL, 1),
(4558026, 656405, 53147, '<td valign="top">Nice smoothness to yoru smoke stream. A shame its not a bit brighter to stand out a bit more against the sky lights below. 7</td>', 'Nice smoothness to yoru smoke stream. A shame its not a bit brighter to stand out a bit more against the sky lights below. 7', '2008-03-12 12:11:28.000000', NULL, 1),
(4558027, 655385, 53147, '<td valign="top">Bad border for this image IMO. Didnt let it affect my vote. Like the layout and the colors.</td>', 'Bad border for this image IMO. Didnt let it affect my vote. Like the layout and the colors.', '2008-03-12 12:12:10.000000', NULL, 1),
(4558031, 656484, 53147, '<td valign="top">Nice simple straightforward image. The duotone processing works well IMO.</td>', 'Nice simple straightforward image. The duotone processing works well IMO.', '2008-03-12 12:12:41.000000', NULL, 1),
(4558032, 657122, 53147, '<td valign="top">Good take on the challenge. Nice to see somethign different. 7</td>', 'Good take on the challenge. Nice to see somethign different. 7', '2008-03-12 12:13:03.000000', NULL, 1),
(4558034, 655387, 53147, '<td valign="top">Cool smoke/steam blur. I like the effect of the multiple stacks.</td>', 'Cool smoke/steam blur. I like the effect of the multiple stacks.', '2008-03-12 12:13:36.000000', NULL, 1),
(4558038, 655312, 53147, '<td valign="top">Good take on the challenge. Simple and straightforward and something a bit different from many of the other entries.</td>', 'Good take on the challenge. Simple and straightforward and something a bit different from many of the other entries.', '2008-03-12 12:14:10.000000', NULL, 1),
(4558041, 656098, 53147, '<td valign="top">I like this shot alot. A family friendly apocolyptic feel to it. Bumping up.</td>', 'I like this shot alot. A family friendly apocolyptic feel to it. Bumping up.', '2008-03-12 12:15:05.000000', NULL, 1),
(4558042, 655925, 53147, '<td valign="top">Great idea. I never would have thought of this. Great colors. Hope this does well for you.</td>', 'Great idea. I never would have thought of this. Great colors. Hope this does well for you.', '2008-03-12 12:15:47.000000', NULL, 1),
(4558289, 656295, 26001, '<td valign="top">very nice exposure. i like that you shot this in an evening ("twilight" zone) to have that beautiful sky instead of during a night in complete dark.</td>', 'very nice exposure. i like that you shot this in an evening ("twilight" zone) to have that beautiful sky instead of during a night in complete dark.', '2008-03-12 14:10:25.000000', NULL, 1),
(4558294, 655387, 26001, '<td valign="top">nice long exposure. that purple hue adds some sort of character and mood to this simple image. just a little too much negative space at the top but no biggie.</td>', 'nice long exposure. that purple hue adds some sort of character and mood to this simple image. just a little too much negative space at the top but no biggie.', '2008-03-12 14:11:51.000000', NULL, 1),
(4558304, 656842, 26001, '<td valign="top">masterfully exposed. do you have any outtake of this image with just a little faster shutter speed than this one though? i like this one nonetheless</td>', 'masterfully exposed. do you have any outtake of this image with just a little faster shutter speed than this one though? i like this one nonetheless', '2008-03-12 14:14:17.000000', NULL, 1),
(4558372, 655260, 73115, '<td valign="top">I like how the face fades out to blackness... nicely done.</td>', 'I like how the face fades out to blackness... nicely done.', '2008-03-12 14:30:56.000000', NULL, 1),
(4558376, 656909, 73115, '<td valign="top">Executed well, but a bit on the uninteresting side for me.</td>', 'Executed well, but a bit on the uninteresting side for me.', '2008-03-12 14:32:36.000000', NULL, 1),
(4558381, 656987, 73115, '<td valign="top">Love the color! Is that a broken lightbulb?</td>', 'Love the color! Is that a broken lightbulb?', '2008-03-12 14:33:58.000000', NULL, 1),
(4558391, 656587, 54778, '<td valign="top">I like how you''ve used repetition to create interest.. the light seems to be rather dreary.. I think using a contrasty b/w conversion might have emphasied the strong structural lines and bring out the details.</td>', 'I like how you''ve used repetition to create interest.. the light seems to be rather dreary.. I think using a contrasty b/w conversion might have emphasied the strong structural lines and bring out the details.', '2008-03-12 14:38:48.000000', NULL, 1),
(4558396, 655394, 54778, '<td valign="top">I find the composition and perspectve quite engaging. Great picture..</td>', 'I find the composition and perspectve quite engaging. Great picture..', '2008-03-12 14:39:44.000000', NULL, 1),
(4558423, 656496, 86447, '<td valign="top">I wish this were leveled up clockwise a smidge.  Good BW image... perfect pollution.</td>', 'I wish this were leveled up clockwise a smidge.  Good BW image... perfect pollution.', '2008-03-12 14:46:58.000000', NULL, 1),
(4558424, 656760, 54778, '<td valign="top">The tones are perfect and I like the pathway on the side..</td>', 'The tones are perfect and I like the pathway on the side..', '2008-03-12 14:47:12.000000', NULL, 1),
(4558427, 656467, 86447, '<td valign="top">More of the can and perhaps the hand would make this a really great shot, IMO.</td>', 'More of the can and perhaps the hand would make this a really great shot, IMO.', '2008-03-12 14:47:52.000000', NULL, 1),
(4558431, 657027, 86447, '<td valign="top">great colors.</td>', 'great colors.', '2008-03-12 14:49:15.000000', NULL, 1),
(4558432, 656654, 54778, '<td valign="top">This image doesn''t have anything specific too focus on that is it''s biggest flaw.. we can see the light has been exposed well but maybe slight illumination on the bridge might have created more interest..</td>', 'This image doesn''t have anything specific too focus on that is it''s biggest flaw.. we can see the light has been exposed well but maybe slight illumination on the bridge might have created more interest..', '2008-03-12 14:49:20.000000', NULL, 1),
(4558435, 656690, 86447, '<td valign="top">It seems tilted to me a bit... pretty reflection.</td>', 'It seems tilted to me a bit... pretty reflection.', '2008-03-12 14:51:06.000000', NULL, 1),
(4558438, 656699, 54778, '<td valign="top">I like the composition as it is but, for the sake of this specific challenge, more of a larger view should have been included in the composition to show what context you''re projecting and a more concrete tie to the pollution theme</td>', 'I like the composition as it is but, for the sake of this specific challenge, more of a larger view should have been included in the composition to show what context you''re projecting and a more concrete tie to the pollution theme', '2008-03-12 14:51:56.000000', NULL, 1),
(4558439, 655424, 73115, '<td valign="top">How terribly sad... even the goats look starved. Love the expression on the girls face.</td>', 'How terribly sad... even the goats look starved. Love the expression on the girls face.', '2008-03-12 14:52:05.000000', NULL, 1),
(4558440, 656959, 73115, '<td valign="top">Interesting... curious as to how this was done.</td>', 'Interesting... curious as to how this was done.', '2008-03-12 14:52:40.000000', NULL, 1),
(4558443, 655312, 73115, '<td valign="top">Nice DOF but lacks in the interesting factor.</td>', 'Nice DOF but lacks in the interesting factor.', '2008-03-12 14:54:20.000000', NULL, 1),
(4558444, 657099, 54778, '<td valign="top">The crop seeems to be slightly too tight.. maybe going backwards and getting more of the location or leaning in further would have helped..</td>', 'The crop seeems to be slightly too tight.. maybe going backwards and getting more of the location or leaning in further would have helped..', '2008-03-12 14:54:22.000000', NULL, 1),
(4558450, 655340, 73115, '<td valign="top">The shadows and hot spot from the flash are distracting. You might try pulling your subject away from the background and/or repositioning your lighting.</td>', 'The shadows and hot spot from the flash are distracting. You might try pulling your subject away from the background and/or repositioning your lighting.', '2008-03-12 14:56:31.000000', NULL, 1),
(4558452, 656796, 73115, '<td valign="top">I like the wide angle here.</td>', 'I like the wide angle here.', '2008-03-12 14:57:07.000000', NULL, 1),
(4558463, 656405, 73115, '<td valign="top">Nice and sharp. I pondered this one for a bit and it seems to me that you can''t really see much on the left side of the street... might be interesting to see the angle changed a little to avoid the left side of the street all together.</td>', 'Nice and sharp. I pondered this one for a bit and it seems to me that you can''t really see much on the left side of the street... might be interesting to see the angle changed a little to avoid the left side of the street all together.', '2008-03-12 15:01:43.000000', NULL, 1),
(4558466, 657070, 77683, '<td valign="top">horizon is a little off, which is distracting.  nice image though!</td>', 'horizon is a little off, which is distracting.  nice image though!', '2008-03-12 15:03:59.000000', NULL, 1),
(4558470, 656068, 77683, '<td valign="top">how is that even remotely safe?</td>', 'how is that even remotely safe?', '2008-03-12 15:06:25.000000', NULL, 1),
(4558480, 655487, 54778, '<td valign="top">Composition wise the trees are definitely unwanted but getting rid of them was not exactly not an option :D I think you''ve been slightly unsuccessful in getting the exposure just right.. The stars are good but the telescope obviously isn''t in focus.. I think you should play around with more different lighting and dof''s to see what fits you criteria best..</td>', 'Composition wise the trees are definitely unwanted but getting rid of them was not exactly not an option :D I think you''ve been slightly unsuccessful in getting the exposure just right.. The stars are good but the telescope obviously isn''t in focus.. I think you should play around with more different lighting and dof''s to see what fits you criteria best..', '2008-03-12 15:10:28.000000', NULL, 1),
(4558498, 655703, 54778, '<td valign="top">The whites seem a bit too over exposed and make me sligthly cross eyed if I look at it too long.. other then that I think you should have added more of the clothes littered all over the floor.. they can definitely add more to your picture''s storytelling ability and composition wise.. I think you should have chosen landscape rather then potrait to present your image..</td>', 'The whites seem a bit too over exposed and make me sligthly cross eyed if I look at it too long.. other then that I think you should have added more of the clothes littered all over the floor.. they can definitely add more to your picture''s storytelling ability and composition wise.. I think you should have chosen landscape rather then potrait to present your image..', '2008-03-12 15:16:38.000000', NULL, 1),
(4558501, 655312, 54778, '<td valign="top">I like the dof and simpleness of the composition here.. The only problem here is the colours.. It all seems a little brown-yellow ish and the contrast of that isn''t exciting enough..</td>', 'I like the dof and simpleness of the composition here.. The only problem here is the colours.. It all seems a little brown-yellow ish and the contrast of that isn''t exciting enough..', '2008-03-12 15:19:05.000000', NULL, 1),
