(4559444, 657057, 88010, '<td valign="top">Shoot for the highlights and let the shadows fall where they may. That was our motto back in the day. But then we also did a fair amount of dodging and burning in the old darkroom. I see the title but I don''t see the pollution.</td>', 'Shoot for the highlights and let the shadows fall where they may. That was our motto back in the day. But then we also did a fair amount of dodging and burning in the old darkroom. I see the title but I don''t see the pollution.', '2008-03-12 20:39:49.000000', NULL, 1),
(4559445, 656796, 88010, '<td valign="top">Maybe a bit underexposed.</td>', 'Maybe a bit underexposed.', '2008-03-12 20:40:07.000000', NULL, 1),
(4559452, 656981, 88010, '<td valign="top">I see the haze but that could be just fog. What I''m saying is that the message of "pollotion" is not jumping out here. In fact, it looks like a pretty picture here.</td>', 'I see the haze but that could be just fog. What I''m saying is that the message of "pollotion" is not jumping out here. In fact, it looks like a pretty picture here.', '2008-03-12 20:41:12.000000', NULL, 1),
(4559456, 656264, 88010, '<td valign="top">Of course this could be nice clean steam, but with global warming I guess that is now also considered polltion. Nice colors, good focus, good exposure.</td>', 'Of course this could be nice clean steam, but with global warming I guess that is now also considered polltion. Nice colors, good focus, good exposure.', '2008-03-12 20:42:21.000000', NULL, 1),
(4559462, 655609, 88010, '<td valign="top">Nice, the best I''ve seen so far ( 15 ). Good colors, it tells a story, has impact.</td>', 'Nice, the best I''ve seen so far ( 15 ). Good colors, it tells a story, has impact.', '2008-03-12 20:43:11.000000', NULL, 1),
(4559468, 656264, 55212, '<td valign="top">Very nice title!</td>', 'Very nice title!', '2008-03-12 20:45:22.000000', NULL, 1),
(4559536, 657026, 58728, '<td valign="top">Beautiful processing.  I also like your composition.  Nice work.</td>', 'Beautiful processing.  I also like your composition.  Nice work.', '2008-03-12 21:06:09.000000', NULL, 1),
(4559540, 657034, 58728, '<td valign="top">Wow, I would hate to have that in my backyard!  Those houses will be hard to sell!</td>', 'Wow, I would hate to have that in my backyard!  Those houses will be hard to sell!', '2008-03-12 21:06:46.000000', NULL, 1),
(4559542, 656988, 58728, '<td valign="top">Nice take on the challenge.  Love her expression!</td>', 'Nice take on the challenge.  Love her expression!', '2008-03-12 21:07:09.000000', NULL, 1),
(4559545, 656901, 58728, '<td valign="top">I love the tilt here.</td>', 'I love the tilt here.', '2008-03-12 21:07:22.000000', NULL, 1),
(4559550, 657093, 58728, '<td valign="top">The smoke looks so good!  you captured it perfectly.</td>', 'The smoke looks so good!  you captured it perfectly.', '2008-03-12 21:07:39.000000', NULL, 1),
(4559555, 656334, 58728, '<td valign="top">Holy flexibility!!!  I love the lines - vertical and the horizontal ones.  Beautiful processing.</td>', 'Holy flexibility!!!  I love the lines - vertical and the horizontal ones.  Beautiful processing.', '2008-03-12 21:08:50.000000', NULL, 1),
(4559559, 655322, 58728, '<td valign="top">I love this.  10.</td>', 'I love this.  10.', '2008-03-12 21:09:49.000000', NULL, 1),
(4559563, 656216, 58728, '<td valign="top">Awesome.</td>', 'Awesome.', '2008-03-12 21:10:10.000000', NULL, 1),
(4559568, 657122, 58728, '<td valign="top">GREAT take on the challenge.</td>', 'GREAT take on the challenge.', '2008-03-12 21:10:58.000000', NULL, 1),
(4559570, 656295, 58728, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-03-12 21:11:21.000000', NULL, 1),
(4559572, 655260, 66784, '<td valign="top">This is a fantastic capture! Excellent timing, very good light, and a very individual interpretation of the subject. Well done!</td>', 'This is a fantastic capture! Excellent timing, very good light, and a very individual interpretation of the subject. Well done!', '2008-03-12 21:11:28.000000', NULL, 1),
(4559577, 655394, 58728, '<td valign="top">great pov.  Really nice processing!</td>', 'great pov.  Really nice processing!', '2008-03-12 21:12:22.000000', NULL, 1),
(4559586, 656274, 58728, '<td valign="top">This makes me sad.  Guess this is real pollution, huh?</td>', 'This makes me sad.  Guess this is real pollution, huh?', '2008-03-12 21:13:15.000000', NULL, 1),
(4559587, 656999, 66784, '<td valign="top">I think this is more cluttered than polluted really. Still, I see your point.</td>', 'I think this is more cluttered than polluted really. Still, I see your point.', '2008-03-12 21:13:15.000000', NULL, 1),
(4559605, 656812, 66784, '<td valign="top">Very good capture! Great combination of saturated colour and transparencies. Never would have thought of this, very original!</td>', 'Very good capture! Great combination of saturated colour and transparencies. Never would have thought of this, very original!', '2008-03-12 21:16:46.000000', NULL, 1),
(4559616, 655609, 66784, '<td valign="top">One of the very good captures of factory pollution in this round. Great colours and balanced exposure. Would like to see a bit more of the subject, maybe there is a better composition there.</td>', 'One of the very good captures of factory pollution in this round. Great colours and balanced exposure. Would like to see a bit more of the subject, maybe there is a better composition there.', '2008-03-12 21:18:58.000000', NULL, 1),
(4559621, 656334, 66784, '<td valign="top">Not the first thing that comes to mind when thinking of pollution. Still, a very good idea and a great shot!</td>', 'Not the first thing that comes to mind when thinking of pollution. Still, a very good idea and a great shot!', '2008-03-12 21:19:45.000000', NULL, 1),
(4559628, 654998, 66784, '<td valign="top">Very dramatic, with beautiful colours and great interplay between light and shadows. Still I have the feeling that something is missing, perhaps the scale of the image is too large to reveal any details. Still like it!</td>', 'Very dramatic, with beautiful colours and great interplay between light and shadows. Still I have the feeling that something is missing, perhaps the scale of the image is too large to reveal any details. Still like it!', '2008-03-12 21:21:07.000000', NULL, 1),
(4559638, 656816, 66784, '<td valign="top">Very good composition, love the symmetry in the shot. I do think though that it lacks punch, maybe colours/contrast needed a bit more fiddling with.</td>', 'Very good composition, love the symmetry in the shot. I do think though that it lacks punch, maybe colours/contrast needed a bit more fiddling with.', '2008-03-12 21:22:46.000000', NULL, 1),
(4559642, 655925, 66784, '<td valign="top">I have the feeling that there''s a great shot somewhere here, with all these colours and patterns. Perhaps isolating some of them would have worked better.</td>', 'I have the feeling that there''s a great shot somewhere here, with all these colours and patterns. Perhaps isolating some of them would have worked better.', '2008-03-12 21:23:37.000000', NULL, 1),
(4559648, 656842, 66784, '<td valign="top">A good subject, well exposed. Would have loved a closer look at this though, with the subject occupying more of the photo. I think that would help with the impact of the shot.</td>', 'A good subject, well exposed. Would have loved a closer look at this though, with the subject occupying more of the photo. I think that would help with the impact of the shot.', '2008-03-12 21:25:21.000000', NULL, 1),
(4559656, 655322, 66784, '<td valign="top">Well spotted and framed. There''s great potential in this shot, but I think the overall image quality is a bit of a let down.</td>', 'Well spotted and framed. There''s great potential in this shot, but I think the overall image quality is a bit of a let down.', '2008-03-12 21:26:49.000000', NULL, 1),
(4559665, 657006, 66784, '<td valign="top">I think that with some extra processing to reveal more of the tones, this could be a very impressive shot.</td>', 'I think that with some extra processing to reveal more of the tones, this could be a very impressive shot.', '2008-03-12 21:28:58.000000', NULL, 1),
(4559670, 656111, 66784, '<td valign="top">A very nice photo, though the element of pollution is not as strong</td>', 'A very nice photo, though the element of pollution is not as strong', '2008-03-12 21:30:33.000000', NULL, 1),
(4559675, 656862, 66784, '<td valign="top">Fantastic! Very minimalistic, perfectly captured, looks stunning. Well done!</td>', 'Fantastic! Very minimalistic, perfectly captured, looks stunning. Well done!', '2008-03-12 21:32:06.000000', NULL, 1),
(4559679, 656317, 66784, '<td valign="top">Well spotted! Good eye for detail here.</td>', 'Well spotted! Good eye for detail here.', '2008-03-12 21:33:22.000000', NULL, 1),
(4559688, 656694, 66784, '<td valign="top">Shocking image. Definitely leaves a lasting impression and puts a message through</td>', 'Shocking image. Definitely leaves a lasting impression and puts a message through', '2008-03-12 21:35:07.000000', NULL, 1),
(4559702, 657067, 66784, '<td valign="top">Interesting idea. However, the background is underexposed, perhaps a different way of lighting the frame would have been better. Keep trying!</td>', 'Interesting idea. However, the background is underexposed, perhaps a different way of lighting the frame would have been better. Keep trying!', '2008-03-12 21:37:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
