(4559752, 656295, 66784, '<td valign="top">A very nice photo, but not really pollution related</td>', 'A very nice photo, but not really pollution related', '2008-03-12 21:43:00.000000', NULL, 1),
(4559761, 656423, 66784, '<td valign="top">This could have been a fantastic shot, but is somehow lacking impact and vibrancy. Well spotted!</td>', 'This could have been a fantastic shot, but is somehow lacking impact and vibrancy. Well spotted!', '2008-03-12 21:44:09.000000', NULL, 1),
