(4562927, 657006, 30454, '<td valign="top">Nice capture, goes well with the challenge. Good luck.</td>', 'Nice capture, goes well with the challenge. Good luck.', '2008-03-13 23:00:34.000000', NULL, 1),
(4562932, 657056, 90806, '<td valign="top">So thats why the first cup of water from the tap always seems to taste rubbery!  Nice shot, just wish the front of the tire was in focus.</td>', 'So thats why the first cup of water from the tap always seems to taste rubbery!  Nice shot, just wish the front of the tire was in focus.', '2008-03-13 23:01:52.000000', NULL, 1),
(4562934, 655609, 30454, '<td valign="top">Good long exposure. Didn''t like composition that much. Good luck.</td>', 'Good long exposure. Didn''t like composition that much. Good luck.', '2008-03-13 23:02:12.000000', NULL, 1),
(4562935, 656336, 31535, '<td valign="top">I would have liked to see the whole shadow. Right now the crop makes the pic look like its missing something.</td>', 'I would have liked to see the whole shadow. Right now the crop makes the pic look like its missing something.', '2008-03-13 23:02:33.000000', NULL, 1),
(4562939, 654998, 30454, '<td valign="top">Nice long exposure. Too small, height wise. Composition doesn''t work for me. Should have included more land at the bottom. Good luck.</td>', 'Nice long exposure. Too small, height wise. Composition doesn''t work for me. Should have included more land at the bottom. Good luck.', '2008-03-13 23:03:44.000000', NULL, 1),
(4562940, 657026, 30454, '<td valign="top">Good HDR here. I like it. Nice colors. Good luck.</td>', 'Good HDR here. I like it. Nice colors. Good luck.', '2008-03-13 23:04:18.000000', NULL, 1),
(4562942, 657093, 90806, '<td valign="top">Striking.  Interesting light flares through the holes in the lower clouds and near the top of the right building.  I think the only thing I don''t really like is the bit of a bright edge all around the silhouetted buildings.</td>', 'Striking.  Interesting light flares through the holes in the lower clouds and near the top of the right building.  I think the only thing I don''t really like is the bit of a bright edge all around the silhouetted buildings.', '2008-03-13 23:05:12.000000', NULL, 1),
