(4563105, 656573, 31535, '<td valign="top">Funny idea. The crop seems a little tight on the bottom and right side.</td>', 'Funny idea. The crop seems a little tight on the bottom and right side.', '2008-03-14 01:17:40.000000', NULL, 1),
