(4563154, 657026, 31535, '<td valign="top">I like the processing you''ve done. Something different. Plus the sky has just enough colour in it to add a little oomph.</td>', 'I like the processing you''ve done. Something different. Plus the sky has just enough colour in it to add a little oomph.', '2008-03-14 01:55:51.000000', NULL, 1),
(4563157, 656959, 31535, '<td valign="top">Great use of colour. I''ve never trid one of these shots, but the symbol just doesn''t look right in your water droplets.</td>', 'Great use of colour. I''ve never trid one of these shots, but the symbol just doesn''t look right in your water droplets.', '2008-03-14 01:58:50.000000', NULL, 1),
