INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4563559, 656760, 89429, '<td valign="top">Great photo.  Nice choice of scene and angle.  The lighting worked out well too.</td>', 'Great photo.  Nice choice of scene and angle.  The lighting worked out well too.', '2008-03-14 09:46:05.000000', NULL, 1),
