(4564959, 656694, 90947, '<td valign="top">What can I say... what a great photojournalism picture.</td>', 'What can I say... what a great photojournalism picture.', '2008-03-15 09:27:13.000000', NULL, 1),
(4565018, 656945, 90892, '<td valign="top">I don''t like the light pollution idea.  It doesn''t seem that it is in keeping with the spirit of the challenge. Beautiful shot though. Upon further review I am bumping this one up a point as it at least shows the light pollutes the sky.</td>', 'I don''t like the light pollution idea.  It doesn''t seem that it is in keeping with the spirit of the challenge. Beautiful shot though. Upon further review I am bumping this one up a point as it at least shows the light pollutes the sky.', '2008-03-15 10:14:34.000000', NULL, 1),
(4565020, 656812, 54778, '<td valign="top">Surprisingly interesting image for something that''s a simple plastic bag.. I like the deep blues and how they permeate through.. But I amost wish the bag was more free flowing..</td>', 'Surprisingly interesting image for something that''s a simple plastic bag.. I like the deep blues and how they permeate through.. But I amost wish the bag was more free flowing..', '2008-03-15 10:15:17.000000', NULL, 1),
(4565041, 655462, 54778, '<td valign="top">I like how the illuminated sky frames the house.. but I''m not sure I like keeping the foreground quite this dark.</td>', 'I like how the illuminated sky frames the house.. but I''m not sure I like keeping the foreground quite this dark.', '2008-03-15 10:25:22.000000', NULL, 1),
(4565050, 657039, 54778, '<td valign="top">The grain actually adds to the appeal of the smoke formation.. To me the lower part seems slightly too busy ..</td>', 'The grain actually adds to the appeal of the smoke formation.. To me the lower part seems slightly too busy ..', '2008-03-15 10:37:26.000000', NULL, 1),
(4565065, 656496, 54778, '<td valign="top">I think you should have straightened the image to get rid of the tilt.. that''s the first thing I noticed instead of the actual image.. The upper half is interesting.. the combination of the smoke and the wires are very appropriate for the challenge.. The lower half is just in the middle of being a silhouette and then not..not sure it looks that great.. I do like how the flag is instatntly recognisable</td>', 'I think you should have straightened the image to get rid of the tilt.. that''s the first thing I noticed instead of the actual image.. The upper half is interesting.. the combination of the smoke and the wires are very appropriate for the challenge.. The lower half is just in the middle of being a silhouette and then not..not sure it looks that great.. I do like how the flag is instatntly recognisable', '2008-03-15 10:52:05.000000', NULL, 1),
(4565071, 656957, 54778, '<td valign="top">I like the dof and the composition but the lighting seems a little harsh...</td>', 'I like the dof and the composition but the lighting seems a little harsh...', '2008-03-15 10:53:54.000000', NULL, 1),
