(4568980, 656812, 51538, '<td valign="top">An NYC kite... nice one.</td>', 'An NYC kite... nice one.', '2008-03-17 08:53:28.000000', NULL, 1),
(4569016, 657068, 89426, '<td valign="top">I really like the colors that you captured in this photograph. The movement up the walls adds a lot to the picture.</td>', 'I really like the colors that you captured in this photograph. The movement up the walls adds a lot to the picture.', '2008-03-17 09:18:34.000000', NULL, 1),
(4569019, 657041, 89426, '<td valign="top">I like this picture in black and white. Most pictures in this shoot are in color. I think this add variety. I like how the pollution on the ground blends in with it''s surroundings.</td>', 'I like this picture in black and white. Most pictures in this shoot are in color. I think this add variety. I like how the pollution on the ground blends in with it''s surroundings.', '2008-03-17 09:21:32.000000', NULL, 1),
(4569023, 656223, 89426, '<td valign="top">I like this photograph. I really like that you captured the bird moving. It makes the picture interesting, where it wouldn''t be other wise.</td>', 'I like this photograph. I really like that you captured the bird moving. It makes the picture interesting, where it wouldn''t be other wise.', '2008-03-17 09:26:05.000000', NULL, 1),
(4569030, 656901, 89426, '<td valign="top">You can''t really tell if this is just a tidal wave, but nice idea. This is a beautiful picture though.</td>', 'You can''t really tell if this is just a tidal wave, but nice idea. This is a beautiful picture though.', '2008-03-17 09:32:34.000000', NULL, 1),
(4569032, 656125, 89426, '<td valign="top">This picture looks a little plain and simple. But the idea is nice gets a good point across.</td>', 'This picture looks a little plain and simple. But the idea is nice gets a good point across.', '2008-03-17 09:35:02.000000', NULL, 1),
(4569033, 656959, 89426, '<td valign="top">This is nice looking, but I have no clue how you did this. The colors and rythm work really well together.</td>', 'This is nice looking, but I have no clue how you did this. The colors and rythm work really well together.', '2008-03-17 09:36:20.000000', NULL, 1),
(4569034, 656317, 89426, '<td valign="top">This is a cute picture. This does show how polluted our world really is. I really like the lighting that you created, or took. The shadow in the corner adds a lot.</td>', 'This is a cute picture. This does show how polluted our world really is. I really like the lighting that you created, or took. The shadow in the corner adds a lot.', '2008-03-17 09:38:31.000000', NULL, 1),
