INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4572581, 656842, 39427, '<td valign="top">congrats on your personal best.  I guess I was wrong about the negative space comment, voters seemed to have loved it.</td>', 'congrats on your personal best.  I guess I was wrong about the negative space comment, voters seemed to have loved it.', '2008-03-19 00:12:49.000000', NULL, 0),
(4572586, 656897, 73115, '<td valign="top">Post Challenge:<br/> <br/>Thanks for all the votes and comments. :)<br/> <br/>I thought I might get a few who would question weather this was considered pollution so I came prepared. ;-) <br/> <br/>The challenge states: "Pollution can appear in many forms. Take a photo of pollution of some kind."<br/> <br/>From Wikipedia - //en.wikipedia.org/wiki/Pollution: Light pollution, includes light trespass, over-illumination and astronomical interference.<br/> <br/>And an entry dedicated solely to Light Pollution - //en.wikipedia.org/wiki/Light_pollution<br/> <br/>And a little more for your reading pleasure - //www.starrynightlights.com/lpIndex.html<br/> <br/>I think it fits quite well. :)<br/></td>', 'Post Challenge: Thanks for all the votes and comments. :) I thought I might get a few who would question weather this was considered pollution so I came prepared. ;-)  The challenge states: "Pollution can appear in many forms. Take a photo of pollution of some kind." From Wikipedia - //en.wikipedia.org/wiki/Pollution: Light pollution, includes light trespass, over-illumination and astronomical interference. And an entry dedicated solely to Light Pollution - //en.wikipedia.org/wiki/Light_pollution And a little more for your reading pleasure - //www.starrynightlights.com/lpIndex.html I think it fits quite well. :)', '2008-03-19 00:14:28.000000', NULL, 0),
(4572596, 655609, 69325, '<td valign="top">top 5! great job roz! big hugs from across the big pond!</td>', 'top 5! great job roz! big hugs from across the big pond!', '2008-03-19 00:16:17.000000', NULL, 0),
(4572599, 655260, 70375, '<td valign="top">This is an AMAZING shot!! Great job Tim!! CONGRATULATIONS!!!</td>', 'This is an AMAZING shot!! Great job Tim!! CONGRATULATIONS!!!', '2008-03-19 00:16:34.000000', NULL, 0),
(4572601, 656295, 73115, '<td valign="top">This was my favorite of the challenge and I had hoped it would do better than it did. I understand where you are coming from regarding those who didn''t feel it met the challenge.  It was spot on!</td>', 'This was my favorite of the challenge and I had hoped it would do better than it did. I understand where you are coming from regarding those who didn''t feel it met the challenge.  It was spot on!', '2008-03-19 00:17:06.000000', NULL, 0),
